// Parse HTML response and convert to Notion blocks
// Note: DOMParser not available in Node.js, using regex-based parsing
const response = $input.first().json;

// Handle if response is wrapped in data/text property
let html = '';
if (typeof response === 'string') {
  html = response;
} else if (response.data) {
  html = response.data;
} else if (response.text) {
  html = response.text;
} else if (response.body) {
  html = response.body;
} else {
  html = JSON.stringify(response);
}

// Remove script, style, and other non-content tags
html = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
html = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
html = html.replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '');
html = html.replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '');
html = html.replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '');
html = html.replace(/<noscript[^>]*>[\s\S]*?<\/noscript>/gi, '');
html = html.replace(/<!--[\s\S]*?-->/g, '');

// Extract title
let title = 'Medium Article - ' + new Date().toISOString().split('T')[0];
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
if (titleMatch) {
  title = titleMatch[1].trim();
}

const blocks = [];

// Add title block
blocks.push({
  object: 'block',
  type: 'heading_1',
  heading_1: {
    rich_text: [{ type: 'text', text: { content: title.substring(0, 1900) } }]
  }
});

// Extract paragraphs
const paraRegex = /<p[^>]*>([\s\S]*?)<\/p>/gi;
let match;
while ((match = paraRegex.exec(html)) !== null) {
  const text = match[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (text && text.length >= 5) {
    blocks.push({
      object: 'block',
      type: 'paragraph',
      paragraph: {
        rich_text: [{ type: 'text', text: { content: text } }]
      }
    });
  }
}

// Extract headings
const headingTags = [
  { tag: 'h1', type: 'heading_1' },
  { tag: 'h2', type: 'heading_2' },
  { tag: 'h3', type: 'heading_3' },
  { tag: 'h4', type: 'heading_3' },
  { tag: 'h5', type: 'heading_3' },
  { tag: 'h6', type: 'heading_3' }
];

for (const ht of headingTags) {
  const headingRegex = new RegExp(`<${ht.tag}[^>]*>([\s\S]*?)<\/${ht.tag}>`, 'gi');
  while ((match = headingRegex.exec(html)) !== null) {
    const text = match[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    if (text) {
      blocks.push({
        object: 'block',
        type: ht.type,
        [ht.type]: {
          rich_text: [{ type: 'text', text: { content: text } }]
        }
      });
    }
  }
}

// Extract list items
const liRegex = /<li[^>]*>([\s\S]*?)<\/li>/gi;
while ((match = liRegex.exec(html)) !== null) {
  const text = match[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (text) {
    blocks.push({
      object: 'block',
      type: 'bulleted_list_item',
      bulleted_list_item: {
        rich_text: [{ type: 'text', text: { content: text } }]
      }
    });
  }
}

// Extract blockquotes
const quoteRegex = /<blockquote[^>]*>([\s\S]*?)<\/blockquote>/gi;
while ((match = quoteRegex.exec(html)) !== null) {
  const text = match[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (text) {
    blocks.push({
      object: 'block',
      type: 'quote',
      quote: {
        rich_text: [{ type: 'text', text: { content: text } }]
      }
    });
  }
}

// Handle long content by splitting into multiple blocks
const finalBlocks = [];
const MAX_CHUNK = 1900;

blocks.forEach(block => {
  const type = block.type;
  if (!block[type] || !block[type].rich_text) {
    finalBlocks.push(block);
    return;
  }

  const richText = block[type].rich_text;
  if (!richText.length) {
    finalBlocks.push(block);
    return;
  }

  const content = richText[0].text?.content || richText[0].text || '';

  if (content.length <= MAX_CHUNK) {
    finalBlocks.push(block);
  } else {
    const chunks = content.match(new RegExp(`.{1,${MAX_CHUNK}}`, 'g')) || [];
    chunks.forEach((chunk) => {
      finalBlocks.push({
        object: 'block',
        type: type,
        [type]: {
          rich_text: [{ type: 'text', text: { content: chunk } }]
        }
      });
    });
  }
});

// Deduplicate consecutive blocks with same content
const dedupedBlocks = [];
finalBlocks.forEach((block) => {
  const prev = dedupedBlocks[dedupedBlocks.length - 1];
  if (prev && prev.type === block.type) {
    const prevContent = prev[prev.type]?.rich_text?.[0]?.text?.content || '';
    const currContent = block[block.type]?.rich_text?.[0]?.text?.content || '';
    if (prevContent === currContent) return;
  }
  dedupedBlocks.push(block);
});

// Limit to 100 blocks
const limitedBlocks = dedupedBlocks.slice(0, 100);

const articleUrl = 'https://medium2.p.rapidapi.com/article/1c560214fbac/html?fullpage=true&style_file=https%3A%2F%2Fmediumapi.com%2Fstyles%2Fdark.css';
const publishedAt = new Date().toISOString();

return [{
  json: {
    pageTitle: title,
    articleUrl: articleUrl,
    publishedAt: publishedAt,
    blocks: limitedBlocks,
    parent: { database_id: '2eff939bda2080858aabe82fd3be2a25' }
  }
}];
